// Rule    : Workload Identity - Service Principal Sign-in from Suspicious Country
// Severity: High
// Tactics : InitialAccess, CredentialAccess
// MITRE   : T1078.004 (Valid Accounts: Cloud Accounts)
// Freq    : PT1H   Period: PT1H
//==========================================================================================

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let HighRiskCountries = dynamic([
    "CN", "RU", "KP", "IR", "NG", "IQ", "PK", "KZ", "UA", "BY",
    "SY", "LY", "YE", "VE", "CU", "ZW", "MM", "AF"
]);
let PrivateRanges = dynamic(["10.", "192.168.", "172.16.", "172.17.", "172.18.",
    "172.19.", "172.20.", "172.21.", "172.22.", "172.23.", "172.24.", "172.25.",
    "172.26.", "172.27.", "172.28.", "172.29.", "172.30.", "172.31.",
    "127.", "169.254.", "168.63."]);
// --- Baseline: countries this SP has historically signed in from ---
let HistoricalCountries = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated between (ago(14d) .. ago(1h))
    | where ResultType == "0"
    | extend GeoInfo = geo_info_from_ip_address(IPAddress)
    | extend Country = tostring(GeoInfo.country_iso_code)
    | where isnotempty(Country)
    | summarize KnownCountries = make_set(Country, 50) by ServicePrincipalId;
// --- Current window ---
(AADServicePrincipalSignInLogs | invoke _ExcludeAllowlistedIPs())
| where TimeGenerated > ago(1h)
| where ResultType == "0"
| where isnotempty(IPAddress)
| where not(IPAddress has_any (PrivateRanges))
| extend GeoInfo = geo_info_from_ip_address(IPAddress)
| extend Country = tostring(GeoInfo.country_iso_code)
| extend City    = tostring(GeoInfo.city)
| where Country in (HighRiskCountries)
| join kind=leftouter HistoricalCountries on ServicePrincipalId
| extend IsNewCountry = not(set_has_element(KnownCountries, Country))
| summarize
    SigninCount     = count(),
    UniqueIPs       = dcount(IPAddress),
    IPList          = make_set(IPAddress, 10),
    Resources       = make_set(ResourceDisplayName, 10),
    Countries       = make_set(Country, 5),
    Cities          = make_set(City, 5),
    CredTypes       = make_set(ClientCredentialType, 5),
    IsNewCountry    = any(IsNewCountry),
    FirstSeen       = min(TimeGenerated),
    LastSeen        = max(TimeGenerated)
    by ServicePrincipalName, ServicePrincipalId, AppId
| extend RiskScore = case(
    IsNewCountry == true,  "Critical",
    UniqueIPs > 3,         "High",
    "Medium")

// Rule    : Workload Identity - Service Principal Brute Force Authentication
// Severity: High
// Tactics : CredentialAccess
// MITRE   : T1110.003 (Brute Force: Password Spraying), T1078.004
// Freq    : PT1H   Period: PT1H
//==========================================================================================

// --- Successful sign-ins in same window (for corroboration) ---
// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let SuccessfulSignins = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated > ago(1h)
    | where ResultType == "0"
    | summarize SuccessCount = count(), SuccessIPs = make_set(IPAddress, 5)
        by ServicePrincipalId;
// --- Failed authentications ---
(AADServicePrincipalSignInLogs | invoke _ExcludeAllowlistedIPs())
| where TimeGenerated > ago(1h)
| where ResultType != "0"
| where ResultType !in ("50076", "50079", "50058", "70044")   // exclude MFA prompts, session expiry (FP)
| summarize
    FailedCount      = count(),
    UniqueIPs        = dcount(IPAddress),
    IPList           = make_set(IPAddress, 20),
    ErrorCodes       = make_set(ResultType, 10),
    ErrorDescriptions = make_set(ResultDescription, 5),
    Resources        = make_set(ResourceDisplayName, 10),
    CredTypes        = make_set(ClientCredentialType, 5),
    FirstAttempt     = min(TimeGenerated),
    LastAttempt      = max(TimeGenerated)
    by ServicePrincipalName, ServicePrincipalId, AppId
| where FailedCount > 20 or UniqueIPs > 5
| join kind=leftouter SuccessfulSignins on ServicePrincipalId
| extend
    SpraySucceeded   = SuccessCount > 0,
    Severity         = case(
        SuccessCount > 0 and FailedCount > 20, "Critical",
        FailedCount > 50,                      "High",
        "Medium")

// Rule    : Workload Identity - Service Principal Token Replay (Same Token, Multiple IPs/Countries)
// Severity: High
// Tactics : CredentialAccess, LateralMovement
// MITRE   : T1528 (Steal Application Access Token), T1550.001
// Freq    : PT1H   Period: PT1H
//==========================================================================================

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let PrivateRanges = dynamic(["10.", "192.168.", "172.16.", "172.17.", "172.18.",
    "172.19.", "172.20.", "172.21.", "172.22.", "172.23.", "172.24.", "172.25.",
    "172.26.", "172.27.", "172.28.", "172.29.", "172.30.", "172.31.",
    "127.", "169.254.", "168.63."]);
(AADServicePrincipalSignInLogs | invoke _ExcludeAllowlistedIPs())
| where TimeGenerated > ago(1h)
| where ResultType == "0"
| where isnotempty(UniqueTokenIdentifier)
| where isnotempty(IPAddress)
| where not(IPAddress has_any (PrivateRanges))
| extend GeoInfo  = geo_info_from_ip_address(IPAddress)
| extend Country  = tostring(GeoInfo.country_iso_code)
| summarize
    UniqueIPs       = dcount(IPAddress),
    UniqueCountries = dcount(Country),
    IPList          = make_set(IPAddress, 10),
    Countries       = make_set(Country, 10),
    UseCount        = count(),
    Resources       = make_set(ResourceDisplayName, 10),
    FirstSeen       = min(TimeGenerated),
    LastSeen        = max(TimeGenerated)
    by UniqueTokenIdentifier, ServicePrincipalName, ServicePrincipalId, AppId
// Token replayed from 3+ different IPs or 2+ countries within the window
| where UniqueIPs >= 3 or UniqueCountries >= 2
| extend
    MinuteSpan    = datetime_diff("minute", LastSeen, FirstSeen),
    RiskLevel     = case(
        UniqueCountries >= 3,                 "Critical",
        UniqueCountries >= 2 and UniqueIPs >= 3, "High",
        "Medium")
| where MinuteSpan <= 60

// Rule    : Workload Identity - SP Conditional Access Bypass → Cloud App Events Correlation
// Severity: High
// Tactics : InitialAccess, Exfiltration
// MITRE   : T1078.004, T1567, T1530
// Freq    : PT1H   Period: PT2H
//==========================================================================================

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let PrivateRanges = dynamic(["10.", "192.168.", "172.16.", "172.17.", "172.18.",
    "172.19.", "172.20.", "172.21.", "172.22.", "172.23.", "172.24.", "172.25.",
    "172.26.", "172.27.", "172.28.", "172.29.", "172.30.", "172.31.",
    "127.", "169.254.", "168.63."]);
let HighRiskActions = dynamic([
    "FileDownloaded", "FileSyncDownloadedFull", "FileDeleted", "FileMoved",
    "SendAs", "MailItemsAccessed", "MassDelete", "DataExfiltration"
]);
// --- SPs that bypassed CA in the last 2 hours ---
let CABypassSPs = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated > ago(2h)
    | where ResultType == "0"
    | where ConditionalAccessStatus in ("notApplied", "failure")
    | where isnotempty(IPAddress)
    | where not(IPAddress has_any (PrivateRanges))
    | project SigninTime = TimeGenerated, ServicePrincipalId, ServicePrincipalName,
        AppId, SigninIP = IPAddress, CAStatus = ConditionalAccessStatus,
        Resource = ResourceDisplayName;
// --- Subsequent high-risk cloud app activity from same SP within 1h ---
// union isfuzzy=true + datatable fallback: deployment succeeds even if CloudAppEvents (M365D connector) is not enabled
union isfuzzy=true
    (CloudAppEvents | invoke _ExcludeAllowlistedIPs()),
    (datatable(TimeGenerated:datetime, ActionType:string, AccountObjectId:string, ObjectName:string, Application:string)[])
| where TimeGenerated > ago(2h)
| where ActionType in (HighRiskActions)
| join kind=inner CABypassSPs on $left.AccountObjectId == $right.ServicePrincipalId
| where TimeGenerated > SigninTime and TimeGenerated <= SigninTime + 1h
| summarize
    ActionCount      = count(),
    Actions          = make_set(ActionType, 10),
    AffectedObjects  = make_set(ObjectName, 20),
    Applications     = make_set(Application, 5),
    SigninIP         = any(SigninIP),
    CAStatus         = any(CAStatus),
    Resource         = any(Resource),
    SigninTime       = any(SigninTime),
    FirstAction      = min(TimeGenerated),
    LastAction       = max(TimeGenerated)
    by ServicePrincipalName, ServicePrincipalId, AppId
| where ActionCount >= 2

// Rule    : Workload Identity - Managed Identity Anomalous Activity Outside Business Hours
// Severity: Medium
// Tactics : Persistence, LateralMovement
// MITRE   : T1078.004, T1550
// Freq    : PT1H   Period: PT1H
//==========================================================================================

// Business hours baseline: 06:00–22:00 weekdays
// Managed Identities authenticating heavily at night/weekends may indicate
// a compromised workload, repurposed VM/container, or attacker pivoting via MI

// --- isfuzzy=true + datatable fallback: deployment succeeds even if AADManagedIdentitySignInLogs is not yet enabled ---
// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let MILogs = union isfuzzy=true
    (AADManagedIdentitySignInLogs | invoke _ExcludeAllowlistedIPs()),
    (datatable(TimeGenerated:datetime, ServicePrincipalId:string, ServicePrincipalName:string,
               ResourceDisplayName:string, SourceAppClientId:string, ResultType:string)[]);
// --- Baseline: normal auth volume per MI during business hours (14d) ---
let BizHoursBaseline = MILogs
    | where TimeGenerated between (ago(14d) .. ago(1h))
    | where ResultType == "0"
    | extend Hour      = hourofday(TimeGenerated)
    | extend IsWeekend = dayofweek(TimeGenerated) in (0d, 6d)
    | where Hour >= 6 and Hour <= 22 and IsWeekend == false
    | summarize
        AvgHourlyAuth = avg(1.0),   // will be computed per-day below
        TotalBizAuth  = count()
        by ServicePrincipalId;
// --- Current hour ---
MILogs
| where TimeGenerated > ago(1h)
| where ResultType == "0"
| extend Hour      = hourofday(TimeGenerated)
| extend IsWeekend = dayofweek(TimeGenerated) in (0d, 6d)
| extend IsOutOfHours = Hour < 6 or Hour > 22 or IsWeekend
| where IsOutOfHours
| summarize
    AuthCount        = count(),
    UniqueResources  = dcount(ResourceDisplayName),
    Resources        = make_set(ResourceDisplayName, 10),
    SourceApps       = make_set(SourceAppClientId, 10),
    UniqueSourceApps = dcount(SourceAppClientId),
    FirstActivity    = min(TimeGenerated),
    LastActivity     = max(TimeGenerated)
    by ServicePrincipalName, ServicePrincipalId
| where AuthCount > 50 or UniqueResources > 10
| join kind=leftouter BizHoursBaseline on ServicePrincipalId
| extend
    IsHighVolume     = AuthCount > 100,
    IsHighSpread     = UniqueResources > 10

// Rule    : Workload Identity - Managed Identity Lateral Movement (High Resource Spread)
// Severity: High
// Tactics : LateralMovement, CredentialAccess, Discovery
// MITRE   : T1550, T1552.001, T1087
// Freq    : PT1H   Period: PT1H
//==========================================================================================

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let SensitiveResourceKeywords = dynamic([
    "Key Vault", "Storage", "SQL", "Cognitive", "OpenAI", "Synapse",
    "Service Bus", "Event Hub", "Container Registry", "Kubernetes"
]);

// --- isfuzzy=true + datatable fallback: deployment succeeds even if AADManagedIdentitySignInLogs is not yet enabled ---
let MILogs = union isfuzzy=true
    (AADManagedIdentitySignInLogs | invoke _ExcludeAllowlistedIPs()),
    (datatable(TimeGenerated:datetime, ServicePrincipalId:string, ServicePrincipalName:string,
               ResourceDisplayName:string, SourceAppClientId:string, ResultType:string)[]);
// --- Baseline: max unique sensitive resources accessed per MI per hour (14d) ---
let Baseline = MILogs
    | where TimeGenerated between (ago(14d) .. ago(1h))
    | where ResultType == "0"
    | where ResourceDisplayName has_any (SensitiveResourceKeywords)
    | summarize HourlyResources = dcount(ResourceDisplayName)
        by ServicePrincipalId, bin(TimeGenerated, 1h)
    | summarize
        MaxHourlyResources = max(HourlyResources),
        AvgHourlyResources = avg(HourlyResources)
        by ServicePrincipalId;

MILogs
| where TimeGenerated > ago(1h)
| where ResultType == "0"
| where ResourceDisplayName has_any (SensitiveResourceKeywords)
| summarize
    AuthCount        = count(),
    UniqueResources  = dcount(ResourceDisplayName),
    Resources        = make_set(ResourceDisplayName, 20),
    SourceApps       = make_set(SourceAppClientId, 10),
    UniqueSourceApps = dcount(SourceAppClientId),
    FirstActivity    = min(TimeGenerated),
    LastActivity     = max(TimeGenerated)
    by ServicePrincipalName, ServicePrincipalId
| where UniqueResources >= 5 or AuthCount > 200
| join kind=leftouter Baseline on ServicePrincipalId
| extend
    ExceedsBaseline  = UniqueResources > MaxHourlyResources * 1.5,
    SpreadScore      = UniqueResources

// Rule    : Workload Identity - SP First-Time Access to Critical Resource Correlated with AuditLogs
// Severity: High
// Tactics : CredentialAccess, Discovery
// MITRE   : T1552.001, T1087.004
// Freq    : PT6H   Period: P14D
//==========================================================================================

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let CriticalResources = dynamic([
    "Microsoft Graph", "Azure Key Vault", "Azure Active Directory",
    "Windows Azure Active Directory", "Azure Resource Manager",
    "Office 365 Exchange Online", "Office 365 SharePoint Online"
]);
let PrivateRanges = dynamic(["10.", "192.168.", "172.16.", "172.17.", "172.18.",
    "172.19.", "172.20.", "172.21.", "172.22.", "172.23.", "172.24.", "172.25.",
    "172.26.", "172.27.", "172.28.", "172.29.", "172.30.", "172.31.",
    "127.", "169.254.", "168.63."]);

// --- Baseline: which SPs have historically accessed each critical resource ---
let HistoricalAccess = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated between (ago(14d) .. ago(6h))
    | where ResultType == "0"
    | where ResourceDisplayName in (CriticalResources)
    | distinct ServicePrincipalId, ResourceDisplayName;

// --- New accesses in current window not seen historically ---
let NewAccesses = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated > ago(6h)
    | where ResultType == "0"
    | where ResourceDisplayName in (CriticalResources)
    | where isnotempty(IPAddress)
    | where not(IPAddress has_any (PrivateRanges))
    | extend GeoInfo = geo_info_from_ip_address(IPAddress)
    | extend Country = tostring(GeoInfo.country_iso_code)
    | join kind=leftanti HistoricalAccess on ServicePrincipalId, ResourceDisplayName
    | summarize
        AccessCount      = count(),
        UniqueIPs        = dcount(IPAddress),
        IPList           = make_set(IPAddress, 5),
        Countries        = make_set(Country, 5),
        CredTypes        = make_set(ClientCredentialType, 5),
        FirstAccess      = min(TimeGenerated),
        LastAccess       = max(TimeGenerated)
        by ServicePrincipalName, ServicePrincipalId, AppId, ResourceDisplayName;

// --- Corroborate: was this SP recently created or had credentials added? ---
let RecentSPChanges = AuditLogs
    | where TimeGenerated > ago(14d)
    | where OperationName has_any (
        "Add service principal", "Add service principal credentials",
        "Update application – Certificates and secrets management",
        "Add application")
    | where Result =~ "success"
    | extend SPName    = tostring(TargetResources[0].displayName)
    | extend SPId      = tostring(TargetResources[0].id)
    | extend Initiator = coalesce(tostring(InitiatedBy.user.userPrincipalName),
        tostring(InitiatedBy.app.displayName))
    | project ChangeTime = TimeGenerated, SPName, SPId, ChangeType = OperationName, Initiator;

NewAccesses
| join kind=leftouter RecentSPChanges on $left.ServicePrincipalId == $right.SPId
| extend IsRecentlyModified = isnotempty(ChangeTime)
| project-away SPName, SPId

// Rule    : Workload Identity - SP Created and Used Same Day from High-Risk Country
// Severity: High
// Tactics : Persistence, InitialAccess
// MITRE   : T1136.003 (Create Cloud Account), T1078.004
// Freq    : PT6H   Period: P1D
//==========================================================================================

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let HighRiskCountries = dynamic([
    "CN", "RU", "KP", "IR", "NG", "IQ", "PK", "KZ", "BY", "SY", "AF"
]);
let PrivateRanges = dynamic(["10.", "192.168.", "172.16.", "172.17.", "172.18.",
    "172.19.", "172.20.", "172.21.", "172.22.", "172.23.", "172.24.", "172.25.",
    "172.26.", "172.27.", "172.28.", "172.29.", "172.30.", "172.31.",
    "127.", "169.254.", "168.63."]);

// --- Service principals created in the last 24 hours ---
let NewSPs = AuditLogs
    | where TimeGenerated > ago(1d)
    | where OperationName =~ "Add service principal"
    | where Result =~ "success"
    | extend SPId        = tostring(TargetResources[0].id)
    | extend SPName      = tostring(TargetResources[0].displayName)
    | extend AppId       = tostring(TargetResources[0].modifiedProperties[0].newValue)
    | extend Creator     = coalesce(tostring(InitiatedBy.user.userPrincipalName),
        tostring(InitiatedBy.app.displayName))
    | project CreatedTime = TimeGenerated, SPId, SPName, Creator;

// --- Sign-ins by those newly created SPs ---
(AADServicePrincipalSignInLogs | invoke _ExcludeAllowlistedIPs())
| where TimeGenerated > ago(1d)
| where ResultType == "0"
| where isnotempty(IPAddress)
| where not(IPAddress has_any (PrivateRanges))
| extend GeoInfo = geo_info_from_ip_address(IPAddress)
| extend Country = tostring(GeoInfo.country_iso_code)
| where Country in (HighRiskCountries)
| join kind=inner NewSPs on $left.ServicePrincipalId == $right.SPId
| where TimeGenerated >= CreatedTime
| summarize
    SigninCount      = count(),
    UniqueIPs        = dcount(IPAddress),
    IPList           = make_set(IPAddress, 5),
    Countries        = make_set(Country, 5),
    Resources        = make_set(ResourceDisplayName, 10),
    MinutesAfterCreate = min(datetime_diff("minute", TimeGenerated, CreatedTime)),
    FirstSignin      = min(TimeGenerated),
    LastSignin       = max(TimeGenerated)
    by ServicePrincipalName, ServicePrincipalId, AppId, Creator, CreatedTime

// Rule    : Workload Identity - SP Credentials Added But No Sign-In Within 24 Hours (Dormant Backdoor)
// Severity: Medium
// Tactics : Persistence
// MITRE   : T1098.001 (Account Manipulation: Additional Cloud Credentials)
// Freq    : PT6H   Period: PT2D
//==========================================================================================
// Attacker adds credentials to an existing SP to establish a persistence backdoor,
// then holds off signing in to avoid detection. If credentials were added 24–48h ago
// and still no sign-in has occurred, this warrants hunting.

// --- Credentials added between 48h and 24h ago ---
// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let CredentialAdditions = AuditLogs
    | where TimeGenerated between (ago(2d) .. ago(24h))
    | where OperationName has_any (
        "Add service principal credentials",
        "Update application – Certificates and secrets management",
        "Update application")
    | where Result =~ "success"
    | extend SPId      = tostring(TargetResources[0].id)
    | extend SPName    = tostring(TargetResources[0].displayName)
    | extend Initiator = coalesce(tostring(InitiatedBy.user.userPrincipalName),
        tostring(InitiatedBy.app.displayName))
    | where isnotempty(SPId)
    | project AddedTime = TimeGenerated, SPId, SPName, Initiator,
        CredType = OperationName;

// --- Any successful sign-ins by those SPs after credential addition ---
let PostAddSignins = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated > ago(2d)
    | where ResultType == "0"
    | distinct ServicePrincipalId;

// --- SPs with creds added but never signed in after ---
CredentialAdditions
| join kind=leftanti PostAddSignins on $left.SPId == $right.ServicePrincipalId
| summarize
    CredAddCount         = count(),
    CredTypes            = make_set(CredType, 5),
    Initiators           = make_set(Initiator, 5),
    ServicePrincipalName = any(SPName),
    FirstAdded           = min(AddedTime),
    LastAdded            = max(AddedTime)
    by SPId
| extend HoursSinceAdd = datetime_diff("hour", now(), LastAdded)

// Rule    : Workload Identity - MI Accessing Key Vault or Storage Correlated with AzureActivity Write
// Severity: Medium
// Tactics : CredentialAccess, Exfiltration
// MITRE   : T1552.001 (Credentials in Files), T1530
// Freq    : PT1H   Period: PT2H
//==========================================================================================
// A Managed Identity that accesses Key Vault or Storage AND triggers write/delete
// operations via the management plane may indicate a compromised workload abusing
// its identity to exfiltrate secrets or data. Correlates AADManagedIdentitySignInLogs
// with AzureActivity to link data-plane auth to management-plane impact.

// --- isfuzzy=true + datatable fallback: deployment succeeds even if AADManagedIdentitySignInLogs is not yet enabled ---
// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let MILogs = union isfuzzy=true
    (AADManagedIdentitySignInLogs | invoke _ExcludeAllowlistedIPs()),
    (datatable(TimeGenerated:datetime, ServicePrincipalId:string, ServicePrincipalName:string,
               ResourceDisplayName:string, SourceAppClientId:string, ResultType:string)[]);
// --- isfuzzy=true + datatable fallback: deployment succeeds even if AzureActivity connector is not yet enabled ---
let AzAct  = union isfuzzy=true
    AzureActivity,
    (datatable(TimeGenerated:datetime, ActivityStatusValue:string, OperationNameValue:string,
               Caller:string, ResourceId:string, ResourceGroup:string, SubscriptionId:string)[]);
// --- MI sign-ins to sensitive data-plane resources ---
let MIDataPlaneAccess = MILogs
    | where TimeGenerated > ago(2h)
    | where ResultType == "0"
    | where ResourceDisplayName has_any ("Key Vault", "Storage", "Blob")
    | project SigninTime = TimeGenerated, ServicePrincipalId, ServicePrincipalName,
        Resource = ResourceDisplayName, SourceAppClientId;

// --- Management plane write/delete operations by the same identity ---
let MgmtPlaneOps = AzAct
    | where TimeGenerated > ago(2h)
    | where ActivityStatusValue =~ "Success"
    | where OperationNameValue has_any ("WRITE", "DELETE")
    | where not(OperationNameValue has_any ("READ", "LIST", "GET"))
    | project OpTime = TimeGenerated, Caller, OperationNameValue,
        ResourceId, ResourceGroup, SubscriptionId;

// --- Correlate by Caller matching ServicePrincipalId or ServicePrincipalName ---
MIDataPlaneAccess
| join kind=inner MgmtPlaneOps on $left.ServicePrincipalId == $right.Caller
| where OpTime >= SigninTime and OpTime <= SigninTime + 1h
| summarize
    DataPlaneAccesses = count(),
    MgmtPlaneOps      = count(),
    Resources         = make_set(Resource, 5),
    Operations        = make_set(OperationNameValue, 10),
    AffectedResources = make_set(ResourceId, 10),
    SubscriptionIds   = make_set(SubscriptionId, 5),
    FirstEvent        = min(SigninTime),
    LastEvent         = max(OpTime)
    by ServicePrincipalName, ServicePrincipalId, ResourceGroup

// Rule    : Workload Identity - SP Sign-in Anomaly Spike (Statistical Baseline Deviation)
// Severity: Medium
// Tactics : Discovery, CredentialAccess
// MITRE   : T1078.004, T1087.004
// Freq    : PT1H   Period: P14D
//==========================================================================================

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let DeviationThreshold = 3.0;    // 3 standard deviations above mean
let MinSigninsThreshold = 50;    // minimum sign-ins in current hour
let MinBaselineDays     = 3;

// --- Baseline: per-SP hourly sign-in counts (last 13 days) ---
let Baseline = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated between (ago(14d) .. ago(1h))
    | where ResultType == "0"
    | summarize HourlySignins = count()
        by ServicePrincipalId, bin(TimeGenerated, 1h)
    | summarize
        AvgPerHour  = avg(HourlySignins),
        StdDevPerHour = stdev(HourlySignins),
        SampleDays  = dcount(bin(TimeGenerated, 1d))
        by ServicePrincipalId
    | where SampleDays >= MinBaselineDays;

// --- Current 1-hour window ---
let CurrentWindow = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated > ago(1h)
    | where ResultType == "0"
    | summarize
        CurrentSignins   = count(),
        UniqueResources  = dcount(ResourceDisplayName),
        Resources        = make_set(ResourceDisplayName, 10),
        UniqueIPs        = dcount(IPAddress),
        CredTypes        = make_set(ClientCredentialType, 5),
        FirstSignin      = min(TimeGenerated),
        LastSignin       = max(TimeGenerated)
        by ServicePrincipalName, ServicePrincipalId, AppId;

CurrentWindow
| join kind=inner Baseline on ServicePrincipalId
| where CurrentSignins >= MinSigninsThreshold
| extend DeviationScore = iff(
    StdDevPerHour > 0,
    (CurrentSignins - AvgPerHour) / StdDevPerHour,
    toreal(CurrentSignins))
| where DeviationScore >= DeviationThreshold
    or (AvgPerHour < 5 and CurrentSignins >= MinSigninsThreshold)
| project
    ServicePrincipalName, ServicePrincipalId, AppId,
    CurrentSignins, AvgPerHour = round(AvgPerHour, 1),
    StdDevPerHour = round(StdDevPerHour, 1),
    DeviationScore = round(DeviationScore, 1),
    UniqueResources, Resources, UniqueIPs, CredTypes,
    FirstSignin, LastSignin

// Rule    : Workload Identity - SP Stale/Dormant Credential Suddenly Activated
// Severity: High
// Tactics : Persistence, InitialAccess
// MITRE   : T1078.004 (Valid Accounts: Cloud Accounts), T1098.001
// Freq    : PT1H   Period: P90D
// NOT a Sentinel built-in: built-in rules track active SPs; this specifically detects
// a sign-in gap of 30+ days followed by sudden reactivation — the attacker dormant-access pattern.
//==========================================================================================
// Stale SPs with active credentials are a standing attack surface. Attackers obtain creds
// for an ownerless SP, wait for the initial suspicious-activity window to pass, then
// reactivate it. This rule fires at the moment of reactivation after a ≥30d dormancy.

// --- Last sign-in per SP in the prior 30d–90d window (dormancy baseline) ---
// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let LastKnownSignin = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated between (ago(90d) .. ago(30d))
    | where ResultType == "0"
    | summarize LastSignin = max(TimeGenerated) by ServicePrincipalId, ServicePrincipalName, AppId;

// --- SPs that have NOT signed in during 0–30d (confirming dormancy) ---
let ActiveInLast30d = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated > ago(30d)
    | where ResultType == "0"
    | distinct ServicePrincipalId;

// --- SPs that were active 30–90d ago but dormant for the last 30d, NOW signing in this hour ---
let NowReactivated = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated > ago(1h)
    | where ResultType == "0"
    | where isnotempty(IPAddress)
    | extend GeoInfo    = geo_info_from_ip_address(IPAddress)
    | extend Country    = tostring(GeoInfo.country_iso_code)
    | extend City       = tostring(GeoInfo.city)
    | summarize
        ReactivationSignins  = count(),
        UniqueIPs            = dcount(IPAddress),
        IPList               = make_set(IPAddress, 5),
        Countries            = make_set(Country, 5),
        Resources            = make_set(ResourceDisplayName, 10),
        CredTypes            = make_set(ClientCredentialType, 5),
        FirstReactivation    = min(TimeGenerated)
        by ServicePrincipalId, ServicePrincipalName, AppId;

// --- Combine: was dormant, now active ---
NowReactivated
| join kind=inner LastKnownSignin on ServicePrincipalId
| join kind=leftanti ActiveInLast30d on ServicePrincipalId
| extend DaysDormant = datetime_diff("day", FirstReactivation, LastSignin)
// --- Correlate: were credentials added during dormancy? (staged backdoor) ---
| join kind=leftouter (
    AuditLogs
    | where TimeGenerated > ago(90d)
    | where OperationName has_any (
        "Add service principal credentials",
        "Update application – Certificates and secrets management")
    | where Result =~ "success"
    | extend SPId      = tostring(TargetResources[0].id)
    | extend Initiator = coalesce(tostring(InitiatedBy.user.userPrincipalName),
        tostring(InitiatedBy.app.displayName))
    | summarize
        CredChanges     = count(),
        CredInitiators  = make_set(Initiator, 5),
        LastCredChange  = max(TimeGenerated)
        by SPId
) on $left.ServicePrincipalId == $right.SPId
| extend CredAddedDuringDormancy = isnotempty(LastCredChange)
    and LastCredChange > LastSignin
    and LastCredChange < FirstReactivation
| extend RiskLevel = case(
    CredAddedDuringDormancy == true and DaysDormant > 60, "Critical",
    CredAddedDuringDormancy == true,                       "High",
    DaysDormant > 60,                                      "High",
    "Medium")
| project
    ServicePrincipalName, ServicePrincipalId, AppId,
    LastSignin, FirstReactivation, DaysDormant,
    ReactivationSignins, UniqueIPs, IPList, Countries, Resources, CredTypes,
    CredAddedDuringDormancy, CredChanges, CredInitiators, LastCredChange, RiskLevel

// Rule    : Workload Identity - SP Graph API Service Principal Enumeration
// Severity: Medium
// Tactics : Discovery
// MITRE   : T1087.004 (Account Discovery: Cloud Account), T1069.003 (Permission Groups: Cloud Groups)
// Freq    : PT1H   Period: PT1H
// Tables  : AuditLogs (Microsoft Graph audit entries)
// Built-in differentiation: No Sentinel built-in detects Graph API SP bulk listing
// by a service principal caller. Microsoft Sentinel "Rare subscription-level operations"
// targets AzureActivity, not Graph API audit events. AzureAD Identity Protection does
// not surface enumeration patterns from non-interactive SP callers.
// Note: Requires Microsoft Entra ID / Azure AD audit log connector. Graph API calls
// to /servicePrincipals appear in AuditLogs with OperationName "List servicePrincipals".
// Tools like AzureHound, ROADtools, and AADInternals generate this pattern at high volume.
//==========================================================================================
// Attackers who compromise an SP use it to enumerate all other SPs in the tenant to
// discover over-privileged apps, legacy credentials, and pivot targets. Listing ≥10 SPs
// via Graph in a single hour from a non-interactive caller is a strong reconnaissance signal.

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let LookbackWindow = 1h;
let SPListingThreshold = 10;    // ≥10 SP list operations = enumeration
let ToolSignatureFilters = dynamic([
    "python-requests", "azurehound", "roadrecon", "aadtools", "pscore",
    "postman", "insomnia", "curl"    // common recon tool UA patterns
]);

// --- Capture Graph API calls to list/read service principals ---
let SPListOps = AuditLogs
    | where TimeGenerated > ago(LookbackWindow)
    | where OperationName in~ (
        "List servicePrincipals",
        "Get servicePrincipal",
        "List servicePrincipal appRoleAssignments",
        "List servicePrincipal memberOf",
        "List servicePrincipal owners",
        "Get servicePrincipal oAuth2PermissionGrants",
        "List application servicePrincipal"
    )
    | where Result =~ "success"
    // Identify if the caller is itself a service principal (non-human)
    | extend CallerType       = case(
        isnotempty(tostring(InitiatedBy.app.servicePrincipalId)), "ServicePrincipal",
        isnotempty(tostring(InitiatedBy.user.id)),                "User",
        "Unknown")
    | extend CallerSPId       = tostring(InitiatedBy.app.servicePrincipalId)
    | extend CallerSPName     = tostring(InitiatedBy.app.displayName)
    | extend CallerUserId     = tostring(InitiatedBy.user.id)
    | extend CallerUpn        = tostring(InitiatedBy.user.userPrincipalName)
    | extend CallerIdentity   = iff(CallerType == "ServicePrincipal", CallerSPName, CallerUpn)
    | extend CallerObjectId   = iff(CallerType == "ServicePrincipal", CallerSPId, CallerUserId)
    | extend TargetSPId       = tostring(TargetResources[0].id)
    | extend TargetSPName     = tostring(TargetResources[0].displayName)
    | extend AdditionalInfo   = tostring(AdditionalDetails);

// --- Aggregate by caller and detect enumeration threshold ---
SPListOps
| summarize
    OpCount           = count(),
    UniqueTargetSPs   = dcount(TargetSPId),
    UniqueOps         = dcount(OperationName),
    TargetSPNames     = make_set(TargetSPName, 30),
    OperationsUsed    = make_set(OperationName, 10),
    FirstOp           = min(TimeGenerated),
    LastOp            = max(TimeGenerated)
    by CallerIdentity, CallerObjectId, CallerType
| where OpCount >= SPListingThreshold
// --- Corroborate: did the same caller recently have new credentials or role grants? ---
| join kind=leftouter (
    AuditLogs
    | where TimeGenerated > ago(24h)
    | where OperationName in (
        "Add service principal credentials",
        "Add app role assignment to service principal",
        "Add delegated permission grant",
        "Update service principal"
    )
    | where Result =~ "success"
    | extend ActorSPId = tostring(InitiatedBy.app.servicePrincipalId)
    | extend ActorUpn  = tostring(InitiatedBy.user.userPrincipalName)
    | extend Actor     = coalesce(ActorSPId, ActorUpn)
    | summarize RecentPrivChanges = count(), PrivOps = make_set(OperationName, 5)
        by Actor
) on $left.CallerObjectId == $right.Actor
| extend RecentPrivChanges   = coalesce(RecentPrivChanges, 0)
| extend HasPrivilegeContext = RecentPrivChanges > 0
| extend DurationMinutes     = datetime_diff("minute", LastOp, FirstOp)
| extend EnumerationRate     = round(todouble(OpCount) / iff(DurationMinutes < 1, 1.0, todouble(DurationMinutes)), 2)
| extend SeverityLevel = case(
    CallerType == "ServicePrincipal" and HasPrivilegeContext, "High — SP enumerating after privilege change",
    CallerType == "ServicePrincipal" and OpCount >= 50,       "High — Bulk SP enumeration by service principal",
    CallerType == "ServicePrincipal",                         "Medium — SP Graph API reconnaissance",
    HasPrivilegeContext,                                      "Medium — User enumeration after privilege change",
    "Medium — Graph API SP enumeration")
| project
    CallerIdentity, CallerObjectId, CallerType,
    OpCount, UniqueTargetSPs, UniqueOps,
    EnumerationRate, DurationMinutes,
    OperationsUsed, TargetSPNames,
    RecentPrivChanges, PrivOps,
    HasPrivilegeContext, SeverityLevel,
    FirstOp, LastOp

// Rule    : Workload Identity - SP Self-Privilege Escalation via App Role Assignment
// Severity: High
// Tactics : PrivilegeEscalation, Persistence
// MITRE   : T1098.003 (Account Manipulation: Additional Cloud Roles)
// Freq    : PT1H   Period: PT1H
// Tables  : AuditLogs
// Built-in differentiation: Sentinel built-in "Service Principal assigned privileged role"
// (id: 9fb57458...) detects Azure RBAC role assignments from a user to an SP. This rule
// specifically detects an SP acting AS THE INITIATOR to add app role assignments to itself
// or grant itself delegated permissions — self-elevation via app registration manipulation,
// a distinct and more stealthy vector. Also fires when an SP grants roles to OTHER SPs
// it controls (lateral privilege spread), which is not covered by any known built-in.
//==========================================================================================
// A compromised SP can call Microsoft Graph to assign itself (or a sibling app) high-value
// app roles like Directory.ReadWrite.All or RoleManagement.ReadWrite.Directory, bypassing
// normal IAM workflows. This is the cloud-native equivalent of a process elevating its own
// token privilege.

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let DangerousAppRoles = dynamic([
    // Microsoft Graph high-value app roles
    "RoleManagement.ReadWrite.Directory",
    "Application.ReadWrite.All",
    "AppRoleAssignment.ReadWrite.All",
    "Directory.ReadWrite.All",
    "User.ReadWrite.All",
    "Group.ReadWrite.All",
    "Mail.ReadWrite",
    "MailboxSettings.ReadWrite",
    "full_access_as_app",
    "Exchange.ManageAsApp",
    // Azure AD roles (via role assignment)
    "Global Administrator",
    "Application Administrator",
    "Cloud Application Administrator",
    "Privileged Role Administrator",
    "Privileged Authentication Administrator"
]);

// --- Find app role assignment and permission grant operations where initiator is an SP ---
AuditLogs
| where TimeGenerated > ago(1h)
| where OperationName in (
    "Add app role assignment to service principal",
    "Add delegated permission grant",
    "Add app role assignment grant",
    "Add member to role",
    "Grant consent to application"
)
| where Result =~ "success"
// Initiator must be a service principal (non-human escalation)
| extend InitiatorSPId   = tostring(InitiatedBy.app.servicePrincipalId)
| extend InitiatorSPName = tostring(InitiatedBy.app.displayName)
| where isnotempty(InitiatorSPId)
// Target of the role grant
| extend TargetObjectId   = tostring(TargetResources[0].id)
| extend TargetObjectName = tostring(TargetResources[0].displayName)
| extend TargetType       = tostring(TargetResources[0].type)
// Determine the actual permission/role granted from modifiedProperties
| mv-expand ModProp = TargetResources[0].modifiedProperties
| where tostring(ModProp.displayName) in (
    "AppRole.Value",
    "DelegatedPermissionGrant.Scope",
    "ServicePrincipal.OAuth2PermissionGrants",
    "Role.DisplayName",
    "Role.TemplateId"
)
| extend GrantedPermission = tostring(ModProp.newValue)
// Filter for dangerous permissions only OR self-assignment regardless of permission
| extend IsSelfGrant      = InitiatorSPId == TargetObjectId
| extend IsDangerousPerm  = GrantedPermission has_any (DangerousAppRoles)
| where IsSelfGrant or IsDangerousPerm
// --- Summarize per initiator SP ---
| summarize
    EscalationCount      = count(),
    GrantedPermissions   = make_set(GrantedPermission, 20),
    TargetObjects        = make_set(TargetObjectName, 10),
    TargetObjectIds      = make_set(TargetObjectId, 10),
    Operations           = make_set(OperationName, 5),
    SelfGrantCount       = countif(IsSelfGrant),
    DangerousPermCount   = countif(IsDangerousPerm),
    FirstEscalation      = min(TimeGenerated),
    LastEscalation       = max(TimeGenerated)
    by InitiatorSPName, InitiatorSPId
// --- Corroborate: was this SP recently created or had credentials added? ---
| join kind=leftouter (
    AuditLogs
    | where TimeGenerated > ago(7d)
    | where OperationName in (
        "Add service principal",
        "Add service principal credentials",
        "Update service principal"
    )
    | where Result =~ "success"
    | extend SPId = tostring(TargetResources[0].id)
    | summarize IsRecentlySeen = count(), RecentOps = make_set(OperationName, 5)
        by SPId
    | extend IsNewOrModified = true
) on $left.InitiatorSPId == $right.SPId
| extend IsNewOrModified = coalesce(IsNewOrModified, false)
| extend SeverityLevel = case(
    SelfGrantCount > 0 and DangerousPermCount > 0, "Critical — SP granted itself dangerous permission",
    SelfGrantCount > 0,                            "High — SP self-grant (any permission)",
    DangerousPermCount > 0 and IsNewOrModified,    "Critical — New/modified SP granting dangerous permissions",
    DangerousPermCount > 0,                        "High — SP granting dangerous permissions to other SP",
    "Medium")
| project
    InitiatorSPName, InitiatorSPId,
    EscalationCount, SelfGrantCount, DangerousPermCount,
    GrantedPermissions, TargetObjects,
    Operations, IsNewOrModified,
    SeverityLevel, FirstEscalation, LastEscalation

// Rule    : Workload Identity - SP Sensitive API Permission Grant Detected
// Severity: High
// Tactics : PrivilegeEscalation, Persistence
// MITRE   : T1098.003 (Account Manipulation: Additional Cloud Roles),
//           T1078.004 (Valid Accounts: Cloud Accounts)
// Freq    : PT1H   Period: PT1H
// Tables  : AuditLogs
// Built-in differentiation: Sentinel built-in "Service Principal assigned privileged role"
// detects Azure RBAC assignment (Microsoft.Authorization role assignments). This rule
// detects OAuth2 / Microsoft Graph API permission consent grants — a separate and equally
// dangerous escalation vector that assigns abilities like reading all mailboxes, writing
// directory objects, or managing all app registrations, which are not Azure RBAC roles.
//==========================================================================================
// Attackers who compromise or control an app registration use OAuth2 permission consent
// to grant the SP access to sensitive Microsoft Graph scopes without assigning any
// traditional Azure RBAC role. These permissions can survive SP certificate rotation
// and are often overlooked in role-based access reviews.

// Sensitive OAuth2 scopes / app roles to monitor
// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let DangerousPermissions = dynamic([
    "RoleManagement.ReadWrite.Directory",   // Can assign any directory role
    "Application.ReadWrite.All",            // Can create/modify apps and add creds
    "AppRoleAssignment.ReadWrite.All",      // Can grant itself or others any app role
    "Directory.ReadWrite.All",              // Full directory write access
    "Mail.ReadWrite",                       // Read/write all mailboxes
    "MailboxSettings.ReadWrite",            // Modify mailbox forwarding rules
    "full_access_as_app",                   // Exchange full tenant access
    "Exchange.ManageAsApp",                 // Exchange management
    "User.ReadWrite.All",                   // Modify all user accounts
    "Group.ReadWrite.All",                  // Modify all groups
    "Contacts.ReadWrite",                   // Access all contact data
    "Files.ReadWrite.All"                   // Read/write all OneDrive/SharePoint files
]);

// --- Capture permission grant events ---
let PermissionGrants = AuditLogs
    | where TimeGenerated > ago(1h)
    | where OperationName in (
        "Add delegated permission grant",
        "Add app role assignment to service principal",
        "Consent to application",
        "Add OAuth2PermissionGrant"
    )
    | where Result =~ "success"
    | extend InitiatorId          = tostring(InitiatedBy.user.id)
    | extend InitiatorUpn         = tostring(InitiatedBy.user.userPrincipalName)
    | extend InitiatorSPId        = tostring(InitiatedBy.app.servicePrincipalId)
    | extend InitiatorDisplayName = coalesce(
        tostring(InitiatedBy.user.userPrincipalName),
        tostring(InitiatedBy.app.displayName),
        "Unknown"
    )
    | extend TargetSPObjectId = tostring(TargetResources[0].id)
    | extend TargetSPName     = tostring(TargetResources[0].displayName)
    // Check the raw modifiedProperties array for the permission value
    | mv-expand ModProp = TargetResources[0].modifiedProperties
    | where tostring(ModProp.displayName) in (
        "DelegatedPermissionGrant.Scope",
        "ServicePrincipal.OAuth2PermissionGrants",
        "AppRole.Value",
        "ServicePrincipal.Oauth2PermissionGrants"
    )
    | extend PermissionValue = tostring(ModProp.newValue)
    | where PermissionValue has_any (DangerousPermissions)
    | summarize
        GrantCount            = count(),
        GrantedPerms          = make_set(PermissionValue, 20),
        TargetSPs             = make_set(TargetSPName, 10),
        TargetSPIds           = make_set(TargetSPObjectId, 10),
        Operations            = make_set(OperationName, 5),
        FirstGrant            = min(TimeGenerated),
        LastGrant             = max(TimeGenerated)
        by InitiatorDisplayName, InitiatorId, InitiatorSPId;

// --- Correlate with recent SP creation (possible new malicious app) ---
let RecentSPCreations = AuditLogs
    | where TimeGenerated > ago(7d)
    | where OperationName == "Add service principal"
    | extend CreatedSPId   = tostring(TargetResources[0].id)
    | extend CreatedSPName = tostring(TargetResources[0].displayName)
    | project CreatedSPId, CreatedSPName, SPCreatedAt = TimeGenerated;

PermissionGrants
| mv-expand TargetSPId = TargetSPIds
| extend TargetSPId = tostring(TargetSPId)
| join kind=leftouter (RecentSPCreations) on $left.TargetSPId == $right.CreatedSPId
| extend IsNewSP                = isnotempty(CreatedSPId) and (LastGrant - SPCreatedAt) < 7d
| extend HasDangerousCombo      = GrantedPerms has "RoleManagement.ReadWrite.Directory"
    or GrantedPerms has "Application.ReadWrite.All"
    or GrantedPerms has "full_access_as_app"
    or GrantedPerms has "Exchange.ManageAsApp"
| extend SeverityLevel = case(
    IsNewSP and HasDangerousCombo, "Critical — New SP granted tenant-wide admin Graph scope",
    HasDangerousCombo,             "High — Dangerous OAuth2 scope granted",
    IsNewSP,                       "High — Sensitive scope granted to recently created SP",
    "Medium — Sensitive Graph API scope granted")
| project-away CreatedSPId, TargetSPId

// Rule    : Workload Identity - Multiple SPs Created by Single Principal in Short Window
// Severity: Medium
// Tactics : Persistence, PrivilegeEscalation
// MITRE   : T1136.003 (Create Account: Cloud Account), T1078.004 (Valid Accounts: Cloud Accounts)
// Freq    : PT30M  Period: PT30M
// Tables  : AuditLogs
// Built-in differentiation: No Sentinel built-in detects bulk SP creation velocity patterns.
// Microsoft Entra ID Protection monitors risky sign-ins but does not detect rapid SP creation
// bursts from a single principal. This is distinct from RULE-09 (SP created never used) which
// is a stale credential hygiene rule — this rule fires on the creation event burst itself,
// well before any dormancy window is reached.
//==========================================================================================
// Attackers who achieve Application Administrator or Cloud App Admin privilege will create
// multiple SPs rapidly to establish persistence (each SP can have independent credentials).
// Automated tools like AzureHound or custom attack payloads generate this burst pattern.
// Legitimate bulk SP creation (e.g., CI/CD pipelines) is typically automated from a known
// service account — alert should be reviewed for unexpected human principals.

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let BurstWindow    = 10m;       // sliding window for burst detection
let BurstThreshold = 3;         // >3 SPs created by same principal within window
let LookbackPeriod = 30m;

// --- All SP creation events in lookback ---
let SPCreations = AuditLogs
    | where TimeGenerated > ago(LookbackPeriod)
    | where OperationName =~ "Add service principal"
    | where Result =~ "success"
    | extend InitiatorType    = case(
        isnotempty(tostring(InitiatedBy.app.servicePrincipalId)), "ServicePrincipal",
        isnotempty(tostring(InitiatedBy.user.id)),                "User",
        "Unknown")
    | extend InitiatorId      = coalesce(
        tostring(InitiatedBy.app.servicePrincipalId),
        tostring(InitiatedBy.user.id))
    | extend InitiatorName    = coalesce(
        tostring(InitiatedBy.app.displayName),
        tostring(InitiatedBy.user.userPrincipalName))
    | extend NewSPId          = tostring(TargetResources[0].id)
    | extend NewSPName        = tostring(TargetResources[0].displayName)
    | project TimeGenerated, InitiatorId, InitiatorName, InitiatorType,
        NewSPId, NewSPName;

// --- Post-creation arming events (joined per-SP before summarize to avoid dynamic-key join) ---
let PostCreationData = AuditLogs
    | where TimeGenerated > ago(LookbackPeriod + 10m)
    | where OperationName in (
        "Add service principal credentials",
        "Add app role assignment to service principal",
        "Add delegated permission grant"
    )
    | where Result =~ "success"
    | extend TargetSPId = tostring(TargetResources[0].id)
    | project TargetSPId, OperationName;
// --- Detect burst: ≥BurstThreshold creations within BurstWindow ---
// Join post-creation ops at per-SP (scalar) level before summarize to avoid dynamic-key join (SEM0713)
SPCreations
| join kind=inner (SPCreations | project InitiatorId, WindowEnd = TimeGenerated) on InitiatorId
| where TimeGenerated between (WindowEnd - BurstWindow .. WindowEnd)
| join kind=leftouter PostCreationData on $left.NewSPId == $right.TargetSPId
| summarize
    CreationsInWindow  = dcount(NewSPId),
    SPsCreated         = make_set(NewSPName, 20),
    SPIds              = make_set(NewSPId, 20),
    PostCreationOps    = dcountif(NewSPId, isnotempty(TargetSPId)),
    PostCreationOpList = make_set_if(OperationName, isnotempty(OperationName), 5),
    WindowStart        = min(TimeGenerated),
    WindowEnd          = max(TimeGenerated)
    by InitiatorId, InitiatorName, InitiatorType
| where CreationsInWindow > BurstThreshold
| extend ImmediateArming   = PostCreationOps > 0
| extend BurstDurationMins = datetime_diff("minute", WindowEnd, WindowStart)
// --- Check if initiator is itself an SP (app creating apps = suspicious) ---
| extend InitiatorIsApp    = InitiatorType == "ServicePrincipal"
| extend SeverityLevel = case(
    InitiatorIsApp and ImmediateArming,  "Critical — SP created SPs and immediately armed them",
    InitiatorIsApp,                      "High — Service principal bulk-created other SPs",
    ImmediateArming,                     "High — Bulk SP creation with immediate credential/role arming",
    CreationsInWindow > 5,               "High — Very high SP creation burst (>5)",
    "Medium — Suspicious SP creation burst")
| project
    InitiatorName, InitiatorId, InitiatorType, InitiatorIsApp,
    CreationsInWindow, BurstDurationMins,
    SPsCreated, SPIds,
    ImmediateArming, PostCreationOps, PostCreationOpList,
    SeverityLevel, WindowStart, WindowEnd

// Hunt     : Workload Identity - SP Activity Correlated with CloudAppEvents (7d)
// Tactics  : Exfiltration, InitialAccess
// MITRE    : T1567, T1530, T1078.004
// Purpose  : Surfaces SPs that authenticated from high-risk geos AND performed high-risk cloud app
//            actions (file downloads, mail access, deletions). Joins AADServicePrincipalSignInLogs
//            with CloudAppEvents on ServicePrincipalId / AccountObjectId. Full 7-day investigation view.
//==========================================================================================

let HighRiskCountries = dynamic([
    "CN", "RU", "KP", "IR", "NG", "IQ", "PK", "KZ", "BY", "AF", "SY"
]);
let HighRiskActions = dynamic([
    "FileDownloaded", "FileSyncDownloadedFull", "FileDeleted", "FileMoved",
    "FileCopied", "SendAs", "MailItemsAccessed", "MassDelete", "DataExfiltration",
    "SharePointFileOperation"
]);
let PrivateRanges = dynamic(["10.", "192.168.", "172.16.", "127.", "169.254.", "168.63."]);
// --- SPs with suspicious sign-ins in the last 7 days ---
let SuspiciousSPSignins = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated > ago(7d)
    | where ResultType == "0"
    | where isnotempty(IPAddress)
    | where not(IPAddress has_any (PrivateRanges))
    | extend GeoInfo = geo_info_from_ip_address(IPAddress)
    | extend Country = tostring(GeoInfo.country_iso_code)
    | where Country in (HighRiskCountries)
        or ConditionalAccessStatus in ("notApplied", "failure")
    | summarize
        SigninCount   = count(),
        Countries     = make_set(Country, 5),
        Resources     = make_set(ResourceDisplayName, 5),
        SigninIPs     = make_set(IPAddress, 10),
        FirstSignin   = min(TimeGenerated),
        LastSignin    = max(TimeGenerated)
        by ServicePrincipalId, ServicePrincipalName, AppId;
// --- Cloud app events by those SPs ---
// isfuzzy=true: CloudAppEvents only exists when Defender for Cloud Apps is connected
union isfuzzy=true
    (CloudAppEvents | invoke ExcludeAllowlistedIPs()),
    (datatable(TimeGenerated:datetime, ActionType:string, AccountObjectId:string,
               ObjectName:string, Application:string, IPAddress:string)[])
| where TimeGenerated > ago(7d)
| where ActionType in (HighRiskActions)
| join kind=inner SuspiciousSPSignins on $left.AccountObjectId == $right.ServicePrincipalId
| summarize
    ActionCount      = count(),
    Actions          = make_set(ActionType, 10),
    AffectedObjects  = make_set(ObjectName, 20),
    Applications     = make_set(Application, 10),
    CloudEventIPs    = make_set(IPAddress, 10),
    Countries        = any(Countries),
    SigninIPs        = any(SigninIPs),
    FirstAction      = min(TimeGenerated),
    LastAction       = max(TimeGenerated)
    by ServicePrincipalName, ServicePrincipalId, AppId
| order by ActionCount desc

