    SPsCreated, SPIds,
    ImmediateArming, PostCreationOps, PostCreationOpList,
    SeverityLevel, WindowStart, WindowEnd

// Rule    : Workload Identity - SP Identity Protection Risk State Escalation
// Severity: High
// Tactics : InitialAccess, CredentialAccess
// MITRE   : T1078.004 (Valid Accounts: Cloud Accounts)
// Freq    : PT1H   Period: PT1H
// Tables  : RiskyServicePrincipals, ServicePrincipalRiskEvents
// Built-in differentiation: The Sentinel built-in "Risky user signed in" and related rules
// target the RiskyUsers table for *user* accounts exclusively. No built-in rule targets
// RiskyServicePrincipals — workload identity risk escalations are completely undetected
// by default even when Identity Protection for Workload Identities is licensed. This rule
// fires the moment Entra ID IP elevates an SP to atRisk or confirmedCompromised at
// medium/high level, and correlates with the specific risk event types that drove it.
//==========================================================================================
// Entra ID Identity Protection evaluates service principal sign-in patterns, API call
// behaviors, and token claims using ML models and Microsoft threat intelligence. An SP
// transition to "atRisk" means the model has high confidence that the identity is being
// abused. A transition to "confirmedCompromised" means a human analyst or automated
// remediation flow has confirmed the finding. Both states warrant immediate investigation.
// Correlation with ServicePrincipalRiskEvents reveals which detection types fired
// (e.g., anomalousToken, investigationsThreatIntelligence) to support triage prioritization.

// --- High-severity event types that warrant Critical escalation ---
// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let HighSeverityEventTypes = dynamic([
    "investigationsThreatIntelligence",   // Microsoft threat intelligence IOC match
    "anomalousToken",                      // Abnormal token characteristics or claims
    "maliciousIPAddress",                  // Sign-in from IP flagged in threat intel feed
    "suspiciousAPITraffic"                 // Unusual API call rate or access pattern
]);

// --- isfuzzy=true: tables only exist when Identity Protection for Workload Identities is licensed ---
let RiskyPrincipals = union isfuzzy=true
    RiskyServicePrincipals,
    (datatable(TimeGenerated:datetime, ServicePrincipalId:string, ServicePrincipalDisplayName:string,
               AppId:string, RiskLevel:string, RiskState:string, RiskDetail:string,
               RiskLastUpdatedDateTime:datetime)[]);
let SPRiskEvents = union isfuzzy=true
    ServicePrincipalRiskEvents,
    (datatable(TimeGenerated:datetime, ServicePrincipalId:string, ServicePrincipalDisplayName:string,
               AppId:string, RiskEventType:string, RiskLevel:string, DetectedDateTime:datetime)[]);
// --- SP risk state escalations in the alert window ---
let EscalatedSPs = RiskyPrincipals
    | where TimeGenerated > ago(1h)
    | where RiskState in ("atRisk", "confirmedCompromised")
    | where RiskLevel in ("high", "medium")
    | project
        ServicePrincipalId, ServicePrincipalDisplayName, AppId,
        RiskLevel, RiskState, RiskDetail, RiskLastUpdatedDateTime;

// --- Enumerate which risk event types drove the escalation ---
let RiskEventsDetail = SPRiskEvents
    | where TimeGenerated > ago(1h)
    | summarize
        RiskEventTypes = make_set(RiskEventType, 10),
        RiskEventCount = count(),
        HighSevCount   = countif(RiskEventType in (HighSeverityEventTypes)),
        FirstDetection = min(DetectedDateTime),
        LastDetection  = max(DetectedDateTime)
        by ServicePrincipalId;

EscalatedSPs
| join kind=leftouter RiskEventsDetail on ServicePrincipalId
| extend RiskEventCount = coalesce(RiskEventCount, 0)
| extend HighSevCount   = coalesce(HighSevCount, 0)
| extend RiskEventTypes = coalesce(RiskEventTypes, dynamic([]))
| extend IsThreatIntelMatch = RiskEventTypes has_any (HighSeverityEventTypes)
| extend SeverityLevel = case(
    RiskState =~ "confirmedCompromised",              "Critical — Identity Protection confirmed SP compromised",
    RiskLevel =~ "high" and IsThreatIntelMatch,       "Critical — High-risk SP with threat intelligence detection",
    RiskLevel =~ "high",                              "High — SP elevated to high risk by Identity Protection",
    "Medium — SP elevated to medium risk by Identity Protection")
| project
    ServicePrincipalDisplayName, ServicePrincipalId, AppId,
    RiskLevel, RiskState, RiskDetail, RiskLastUpdatedDateTime,
    RiskEventTypes, RiskEventCount, HighSevCount,
    IsThreatIntelMatch, SeverityLevel,
    FirstDetection, LastDetection

// Rule    : Workload Identity - SP Risk Event Stacking (Multiple Concurrent Detections)
// Severity: High
// Tactics : CredentialAccess, Persistence
// MITRE   : T1078.004 (Valid Accounts: Cloud Accounts), T1550.001 (Use Alternate Auth Material)
// Freq    : PT1H   Period: PT1H
// Tables  : ServicePrincipalRiskEvents, AADServicePrincipalSignInLogs
// Built-in differentiation: No Sentinel built-in correlates multiple distinct risk event
// types for the same SP within a time window. Risk stacking — where ≥2 independent
// Identity Protection models fire simultaneously — is statistically unlikely for benign SPs
// and is a strong indicator of active exploitation rather than a false positive. This rule
// also fires as soon as any single high-severity event type triggers (anomalousToken,
// investigationsThreatIntelligence, maliciousIPAddress, suspiciousAPITraffic).
//==========================================================================================
// When an attacker actively abuses a compromised SP, their techniques typically trigger
// multiple independent Entra ID Identity Protection detection models at once:
//   anomalousToken          – stolen token reused with abnormal claims or lifetime
//   maliciousIPAddress      – sign-in origin IP appears in Microsoft threat intel
//   suspiciousAPITraffic    – unusual API call rate, resource spread, or access pattern
//   investigationsThreatIntelligence – direct IOC match from Microsoft threat intelligence
// Stacking ≥2 event types for the same SP within 1 hour is a compound signal that
// distinguishes active exploitation from isolated model noise. Correlation with active
// sign-in activity in AADServicePrincipalSignInLogs further confirms live exploitation.

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let HighSeverityEventTypes = dynamic([
    "investigationsThreatIntelligence",
    "anomalousToken",
    "maliciousIPAddress",
    "suspiciousAPITraffic"
]);
// --- isfuzzy=true: table only exists when Identity Protection for Workload Identities is licensed ---
let SPRiskEvents = union isfuzzy=true
    ServicePrincipalRiskEvents,
    (datatable(TimeGenerated:datetime, ServicePrincipalId:string, ServicePrincipalDisplayName:string,
               AppId:string, RiskEventType:string, RiskLevel:string, DetectedDateTime:datetime)[]);

SPRiskEvents
| where TimeGenerated > ago(1h)
| where RiskLevel in ("high", "medium") or RiskEventType in (HighSeverityEventTypes)
| summarize
    EventCount         = count(),
    UniqueEventTypes   = dcount(RiskEventType),
    EventTypes         = make_set(RiskEventType, 10),
    HighSeverityEvents = countif(RiskEventType in (HighSeverityEventTypes)),
    HighLevelCount     = countif(RiskLevel == "high"),
    FirstEvent         = min(DetectedDateTime),
    LastEvent          = max(DetectedDateTime)
    by ServicePrincipalId, ServicePrincipalDisplayName, AppId
| where UniqueEventTypes >= 2 or HighSeverityEvents >= 1
// --- Correlate with concurrent sign-in activity to confirm live exploitation ---
| join kind=leftouter (
    (AADServicePrincipalSignInLogs | invoke _ExcludeAllowlistedIPs())
    | where TimeGenerated > ago(1h)
    | summarize
        ConcurrentSignins = count(),
        SuccessfulSignins = countif(ResultType == "0"),
        UniqueIPs         = dcount(IPAddress),
        Countries         = make_set(Location, 5),
        SigninResources   = make_set(ResourceDisplayName, 5)
        by ServicePrincipalId
) on ServicePrincipalId
| extend ConcurrentSignins   = coalesce(ConcurrentSignins, 0)
| extend SuccessfulSignins   = coalesce(SuccessfulSignins, 0)
| extend IsActivelyBeingUsed = ConcurrentSignins > 0
| extend SeverityLevel = case(
    HighSeverityEvents >= 1 and IsActivelyBeingUsed, "Critical — High-severity risk detection concurrent with active sign-ins",
    HighSeverityEvents >= 1,                         "High — High-severity risk event type triggered",
    UniqueEventTypes >= 3,                            "High — 3+ distinct risk event types stacked",
    IsActivelyBeingUsed and UniqueEventTypes >= 2,   "High — Risk stacking with active concurrent sign-in",
    "Medium — Multiple risk event types without active sign-in")
| project
    ServicePrincipalDisplayName, ServicePrincipalId, AppId,
    EventCount, UniqueEventTypes, EventTypes,
    HighSeverityEvents, HighLevelCount,
    IsActivelyBeingUsed, ConcurrentSignins, SuccessfulSignins,
    UniqueIPs, Countries, SigninResources,
    SeverityLevel, FirstEvent, LastEvent

// Rule    : Workload Identity - SP Credential Modified by Risky User with Concurrent M365 Activity
// Severity: High
// Tactics : Persistence, CredentialAccess, Collection
// MITRE   : T1098.001 (Additional Cloud Credentials), T1078.004 (Valid Accounts: Cloud Accounts), T1530
// Freq    : PT1H   Period: PT1H
// Tables  : AADRiskyUsers, AuditLogs, OfficeActivity
// Built-in differentiation: Sentinel built-ins for credential changes do not correlate the
// initiating user's current Identity Protection risk state, nor do they cross-reference
// concurrent M365 data access by the same user. This rule combines all three signals:
// active risk state + SP credential change + concurrent OfficeActivity, confirming that
// the compromised account is simultaneously staging data while installing persistent access.
//==========================================================================================
// A user flagged in Entra Identity Protection modifying SP credentials is the canonical
// lateral movement pivot. Adding OfficeActivity correlation reveals whether the attacker
// is also performing M365 data operations (Exchange mail access, SharePoint downloads,
// Teams channel reads) in the same window — the compound signal separates active
// multi-vector exploitation from isolated audit noise.

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let LookbackWindow = 1h;
let CredentialOps = dynamic([
    "Add service principal credentials",
    "Remove service principal credentials",
    "Add password to service principal",
    "Add key credential to service principal",
    "Remove password from service principal",
    "Remove key credential from service principal",
    "Add owner to service principal",
    "Add owner to application",
    "Update application \u2013 Certificates and secrets management (by service)"
]);

// Active risky users — risk not yet dismissed or remediated
let RiskyUsers = union isfuzzy=true
    AADRiskyUsers,
    (datatable(Id:string, UserPrincipalName:string, RiskLevel:string,
               RiskState:string, RiskDetail:string,
               RiskLastUpdatedDateTime:datetime)[])
    | where RiskState in ("atRisk", "confirmedCompromised")
    | where RiskLevel in ("high", "medium")
    | project UserId = Id, UserPrincipalName, RiskLevel, RiskState, RiskDetail;

// SP credential changes by risky users
let CredChanges = AuditLogs
    | where TimeGenerated > ago(LookbackWindow)
    | where OperationName has_any (CredentialOps)
    | where Result =~ "success"
    | where isnotempty(tostring(InitiatedBy.user.id))
    | extend InitiatorUserId = tostring(InitiatedBy.user.id)
    | extend InitiatorUPN    = tostring(InitiatedBy.user.userPrincipalName)
    | extend InitiatorIP     = tostring(InitiatedBy.user.ipAddress)
    | extend TargetId        = tostring(TargetResources[0].id)
    | extend TargetName      = tostring(TargetResources[0].displayName)
    | join kind=inner RiskyUsers on $left.InitiatorUserId == $right.UserId
    | summarize
        EventCount   = count(),
        Operations   = make_set(OperationName, 10),
        TargetSPs    = make_set(TargetName, 10),
        TargetSPIds  = make_set(TargetId, 10),
        InitiatorIPs = make_set(InitiatorIP, 5),
        RiskLevel    = any(RiskLevel),
        RiskState    = any(RiskState),
        RiskDetail   = any(RiskDetail),
        FirstSeen    = min(TimeGenerated),
        LastSeen     = max(TimeGenerated)
        by InitiatorUserId, InitiatorUPN;

// Concurrent OfficeActivity from the same risky user — M365 data plane impact
let M365Activity = OfficeActivity
    | where TimeGenerated > ago(LookbackWindow)
    | where isnotempty(UserId)
    | extend UserIdLower = tolower(UserId)
    | summarize
        M365OperationCount = count(),
        M365Operations     = make_set(Operation, 10),
        M365Workloads      = make_set(OfficeWorkload, 5),
        M365ResourceCount  = dcount(OfficeObjectId),
        M365Resources      = make_set(OfficeObjectId, 5),
        M365ClientIPs      = make_set(ClientIP, 5)
        by UserIdLower;

CredChanges
| extend UserIdLower = tolower(InitiatorUPN)
| join kind=leftouter M365Activity on UserIdLower
| extend AlertSeverity = case(
    RiskState == "confirmedCompromised" and M365OperationCount > 0, "Critical",
    RiskState == "confirmedCompromised",                             "High",
    M365OperationCount > 0,                                          "High",
    "Medium")
| project
    InitiatorUPN, InitiatorUserId, RiskLevel, RiskState, RiskDetail,
    EventCount, Operations, TargetSPs, TargetSPIds, InitiatorIPs,
    M365OperationCount, M365Operations, M365Workloads,
    M365ResourceCount, M365Resources, M365ClientIPs,
    AlertSeverity, FirstSeen, LastSeen
| order by AlertSeverity asc, EventCount desc

// Rule    : Workload Identity - Risky User Grants App Roles with Concurrent M365 Data Access
// Severity: High
// Tactics : Persistence, PrivilegeEscalation, Collection
// MITRE   : T1098.003 (Account Manipulation: Additional Cloud Roles), T1548, T1530
// Freq    : PT1H   Period: PT1H
// Tables  : AADUserRiskEvents, AuditLogs, OfficeActivity
// Built-in differentiation: No Sentinel built-in correlates Identity Protection risk event
// timing with privilege grant operations, and none cross-references concurrent M365 data
// access from the same account. The triple signal — risk event + privilege grant +
// OfficeActivity data ops — distinguishes deliberate multi-vector attacks from isolated
// misconfiguration events.
//==========================================================================================
// Attack chain: attacker compromises a user account (Identity Protection fires a risk
// event) → grants elevated app roles or OAuth consent on a controlled SP → simultaneously
// accesses Exchange/SharePoint/Teams to stage or exfiltrate data. The proximity between
// risk detection, privilege installation, and M365 data access is the diagnostic signal.

// ---- Network Allowlist (exclude trusted IPs / CIDR / ranges) --------------
let _allow = materialize(union isfuzzy=true (print R="" | take 0), (_GetWatchlist('NetworkAllowlist') | project R = tostring(IPOrRange)) | where isnotempty(R));
let _allowCIDR  = toscalar(_allow | where not(R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$') | extend R = iff(R has '/', R, strcat(R, '/32')) | summarize make_list(R));
let _allowRange = toscalar(_allow | where R matches regex @'^\d+\.\d+\.\d+\.\d+-\d+\.\d+\.\d+\.\d+$' | summarize make_list(R));
let _ExcludeAllowlistedIPs = (T:(IPAddress:string)) {
    T
    | extend IPAddress = tostring(IPAddress)
    | where array_length(_allowCIDR) == 0 or isnull(ipv4_is_in_any_range(IPAddress, _allowCIDR)) or not(ipv4_is_in_any_range(IPAddress, _allowCIDR))
    | mv-apply _r = _allowRange to typeof(string) on (
        extend _lo = tostring(split(_r,'-')[0]), _hi = tostring(split(_r,'-')[1])
        | extend _inRange = ipv4_compare(IPAddress, _lo) >= 0 and ipv4_compare(IPAddress, _hi) <= 0
        | summarize _anyInRange = max(toint(_inRange)))
    | where isnull(_anyInRange) or _anyInRange == 0
    | project-away _anyInRange
};
// ---------------------------------------------------------------------------
let LookbackWindow = 1h;
let RiskLookback   = 24h;

let PrivilegeGrantOps = dynamic([
    "Add app role assignment to service principal",
    "Add delegated permission grant",
    "Add app role assignment grant to user",
    "Add OAuth2PermissionGrant",
    "Consent to application",
    "Add member to role",
    "Grant an application permission to user",
    "Add application",
    "Add service principal"
]);

// Users who triggered a risk event in the past 24 hours
let RecentRiskyUsers = union isfuzzy=true
    AADUserRiskEvents,
    (datatable(UserId:string, UserPrincipalName:string, RiskEventType:string,
               RiskLevel:string, DetectedDateTime:datetime)[])
    | where DetectedDateTime > ago(RiskLookback)
    | where RiskLevel in ("high", "medium")
    | summarize
        RiskEventTypes = make_set(RiskEventType, 10),
        MaxRiskLevel   = max(RiskLevel),
        FirstRisk      = min(DetectedDateTime),
        LastRisk       = max(DetectedDateTime)
        by UserId, UserPrincipalName;

// Privilege grants by risky users in current window
let PrivGrants = AuditLogs
    | where TimeGenerated > ago(LookbackWindow)
    | where OperationName has_any (PrivilegeGrantOps)
    | where Result =~ "success"
    | where isnotempty(tostring(InitiatedBy.user.id))
    | extend InitiatorUserId = tostring(InitiatedBy.user.id)
    | extend InitiatorUPN    = tostring(InitiatedBy.user.userPrincipalName)
    | extend InitiatorIP     = tostring(InitiatedBy.user.ipAddress)
    | extend TargetId        = tostring(TargetResources[0].id)
    | extend TargetName      = tostring(TargetResources[0].displayName)
    | join kind=inner RecentRiskyUsers on $left.InitiatorUserId == $right.UserId
    | extend TimeSinceRisk   = datetime_diff("minute", TimeGenerated, LastRisk)
    | summarize
        GrantCount       = count(),
        Operations       = make_set(OperationName, 10),
        TargetApps       = make_set(TargetName, 10),
        InitiatorIPs     = make_set(InitiatorIP, 5),
        RiskEventTypes   = any(RiskEventTypes),
        MaxRiskLevel     = any(MaxRiskLevel),
        LastRisk         = any(LastRisk),
        MinTimeSinceRisk = min(TimeSinceRisk),
        FirstSeen        = min(TimeGenerated),
        LastSeen         = max(TimeGenerated)
        by InitiatorUserId, InitiatorUPN;

// Concurrent OfficeActivity from the same risky user
let M365Activity = OfficeActivity
    | where TimeGenerated > ago(LookbackWindow)
    | where isnotempty(UserId)
    | extend UserIdLower = tolower(UserId)
    | summarize
        M365OperationCount = count(),
        M365Operations     = make_set(Operation, 10),
        M365Workloads      = make_set(OfficeWorkload, 5),
        M365ResourceCount  = dcount(OfficeObjectId),
        M365Resources      = make_set(OfficeObjectId, 5),
        M365ClientIPs      = make_set(ClientIP, 5)
        by UserIdLower;

PrivGrants
| extend UserIdLower = tolower(InitiatorUPN)
| join kind=leftouter M365Activity on UserIdLower
| extend AlertSeverity = case(
    MaxRiskLevel == "high" and M365OperationCount > 0, "High",
    MaxRiskLevel == "high",                             "High",
    M365OperationCount > 0,                             "Medium",
    "Medium")
| project
    InitiatorUPN, InitiatorUserId, MaxRiskLevel, RiskEventTypes,
    LastRisk, MinTimeSinceRisk,
    GrantCount, Operations, TargetApps, InitiatorIPs,
    M365OperationCount, M365Operations, M365Workloads,
    M365ResourceCount, M365Resources, M365ClientIPs,
    AlertSeverity, FirstSeen, LastSeen
| order by AlertSeverity asc, GrantCount desc

// Hunt    : Workload Identity - CloudAppEvents SP/OAuth App Access Anomaly Profile (30d)
// Purpose : Profiles all service principals and OAuth applications visible in CloudAppEvents
//           over 30 days, ranked by volume, object diversity, and unique user spread. Joins
//           with AADServicePrincipalSignInLogs to add authentication metadata (IPs, cred types,
//           countries). Identifies applications performing broad collection, mass enumeration,
//           or cross-user access patterns that exceed normal operational behaviour. Use to
//           baseline legitimate automation and surface abnormal data-access footprints.
// Tables  : CloudAppEvents, AADServicePrincipalSignInLogs
// Period  : P30D
// Tactics : Collection, Discovery, Exfiltration
// MITRE   : T1530, T1213, T1087.004
//==========================================================================================

let LookbackDays      = 30d;
let HighVolumeActions = dynamic([
    "FileDownloaded", "FileRead", "FilePreviewed", "FileCopied", "FileSyncUploadedFull",
    "FolderListed", "SearchQueried",
    "MailItemsAccessed", "MessageRead", "Send",
    "TeamsMessageRead"
]);
let LowVolumeActions  = dynamic([
    "FileCreated", "FileModified", "FileUploaded",
    "MeetingParticipant", "UserLoggedIn"
]);

// Per-app profile from CloudAppEvents
let AppProfile = CloudAppEvents | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated > ago(LookbackDays)
    | where isnotempty(tostring(ApplicationId))
    | extend AppIdStr    = tostring(ApplicationId)
    | extend AppName     = tostring(Application)
    | extend IPAddr      = tostring(IPAddress)
    | extend Country     = tostring(CountryCode)
    | extend ObjName     = tostring(ObjectName)
    | extend ActorUpn    = tostring(AccountUpn)
    | summarize
        TotalActions       = count(),
        HighVolumeActions  = countif(ActionType in~ (HighVolumeActions)),
        LowVolumeActions   = countif(ActionType in~ (LowVolumeActions)),
        UniqueObjects      = dcount(ObjName),
        UniqueUsers        = dcount(ActorUpn),
        UniqueIPs          = dcount(IPAddr),
        ActionTypes        = make_set(ActionType, 15),
        TopObjects         = make_set(ObjName, 10),
        Countries          = make_set(Country, 5),
        AppName            = any(AppName),
        FirstSeen          = min(TimeGenerated),
        LastSeen           = max(TimeGenerated)
        by AppIdStr;

// SP sign-in metadata from AADServicePrincipalSignInLogs
let SPSigninProfile = AADServicePrincipalSignInLogs | invoke ExcludeAllowlistedIPs()
    | where TimeGenerated > ago(LookbackDays)
    | where ResultType == "0"
    | summarize
        SigninCount        = count(),
        SigninIPs          = dcount(IPAddress),
        SigninIPList       = make_set(IPAddress, 10),
        CredTypes          = make_set(ClientCredentialType, 5),
        Resources          = make_set(ResourceDisplayName, 10),
        SigninCountries    = make_set(Location, 5),
        FailedSignins      = countif(ResultType != "0"),
        FirstSignin        = min(TimeGenerated),
        LastSignin         = max(TimeGenerated)
        by AppId, ServicePrincipalName, ServicePrincipalId;

// Join profiles
AppProfile
| join kind=leftouter SPSigninProfile on $left.AppIdStr == $right.AppId
| extend HighVolumeRatio   = round(todouble(HighVolumeActions) / iff(TotalActions > 0, todouble(TotalActions), 1.0), 2)
| extend UserSpreadRatio   = round(todouble(UniqueUsers) / iff(UniqueObjects > 0, todouble(UniqueObjects), 1.0), 2)
| extend AnomalyScore      = case(
    HighVolumeRatio > 0.8 and UniqueUsers > 20,  "Critical",
    HighVolumeRatio > 0.6 and UniqueObjects > 50, "High",
    HighVolumeRatio > 0.4,                         "Medium",
    "Low")
| project
    AppIdStr, AppName, ServicePrincipalId, ServicePrincipalName,
    TotalActions, HighVolumeActions, HighVolumeRatio,
    UniqueObjects, UniqueUsers, UniqueIPs, UserSpreadRatio,
    ActionTypes, TopObjects, Countries,
    SigninCount, SigninIPs, SigninIPList, CredTypes, Resources, SigninCountries,
    AnomalyScore, FirstSeen, LastSeen
| order by TotalActions desc
